mapper.select:
        { CALL SP_BOARD_LIST(
            #{startNum, mode=IN, jdbcType=INTEGER},
            #{endNum, mode=IN, jdbcType=INTEGER},
            #{resultCursor, mode=OUT, jdbcType=CURSOR,
              javaType=java.sql.ResultSet,
              resultMap=boardListMap}
        )}

SELECT BOARD_ID, TITLE, WRITER, VIEW_COUNT, 
TO_CHAR(CREATED_DATE, 'YYYY-MM-DD HH24:MI:SS') as CREATED_DATE, 
TO_CHAR(CONTENT) AS CONTENT FROM BOARD WHERE BOARD_ID = #{boardId}
